"""
Deterministic Quota Planner for Multi-Page Batching and Budget Management (Phase 13).

Calculates request requirements, determines feasibility under budget constraints,
and plans deterministic page batches prioritized by structural relevance scores.
"""

import math
from typing import List, Dict, Optional, Tuple
from pydantic import BaseModel, Field


class QuotaPlan(BaseModel):
    """Execution plan generated by QuotaPlanner."""
    eligible_pages_count: int = Field(..., description="Total pages requiring extraction")
    available_requests: Optional[int] = Field(None, description="Configured Gemini request limit")
    batch_size: int = Field(..., description="Configured page batch size (1, 2, 3, 5)")
    estimated_requests: int = Field(..., description="Requests required for full extraction")
    can_complete: bool = Field(..., description="Whether full extraction fits in available requests")
    full_extraction_possible: bool = Field(..., description="Alias for can_complete")
    pages_planned: List[int] = Field(default_factory=list, description="Ordered list of pages to be processed")
    pages_deferred: List[int] = Field(default_factory=list, description="Pages that cannot be processed under budget")
    batches: List[List[int]] = Field(default_factory=list, description="Page groupings per Gemini request")
    remaining_budget: Optional[int] = Field(None, description="Unused request budget after planned execution")


class QuotaPlanner:
    """
    Deterministic planning engine for batching and quota-aware partial extraction.
    Never makes network or LLM calls.
    """

    def __init__(self, default_batch_size: int = 2):
        self.default_batch_size = max(1, default_batch_size)

    def calculate_plan(
        self,
        eligible_pages: List[int],
        request_budget: Optional[int] = None,
        batch_size: Optional[int] = None,
        page_relevance_scores: Optional[Dict[int, float]] = None,
    ) -> QuotaPlan:
        """
        Computes the deterministic extraction plan for a set of eligible pages.
        
        Args:
            eligible_pages: List of 1-indexed page numbers.
            request_budget: Optional positive integer representing max allowed Gemini requests.
            batch_size: Pages per Gemini call (e.g. 1, 2, 3, 5). Defaults to default_batch_size.
            page_relevance_scores: Optional map of page_number -> float score (e.g. from Phase 11).
        
        Returns:
            QuotaPlan with exact batch assignments and processed/deferred pages.
        """
        size = batch_size if (batch_size is not None and batch_size > 0) else self.default_batch_size
        clean_pages = sorted(list(set(p for p in eligible_pages if p >= 1)))
        total_pages = len(clean_pages)

        if total_pages == 0:
            return QuotaPlan(
                eligible_pages_count=0,
                available_requests=request_budget,
                batch_size=size,
                estimated_requests=0,
                can_complete=True,
                full_extraction_possible=True,
                pages_planned=[],
                pages_deferred=[],
                batches=[],
                remaining_budget=request_budget,
            )

        estimated_requests = math.ceil(total_pages / size)

        # Determine completion feasibility
        if request_budget is None or request_budget <= 0:
            # Unlimited budget
            can_complete = True
            max_processable_pages = total_pages
        else:
            can_complete = (request_budget >= estimated_requests)
            max_processable_pages = min(total_pages, request_budget * size)

        # Prioritize pages if budget is constrained
        if can_complete or page_relevance_scores is None:
            # All planned in original order
            pages_planned = clean_pages[:max_processable_pages]
            pages_deferred = clean_pages[max_processable_pages:]
        else:
            # Sort by relevance score (descending), then by page number (ascending)
            ranked_pages = sorted(
                clean_pages,
                key=lambda p: (page_relevance_scores.get(p, 0.5), -p),
                reverse=True,
            )
            selected_set = set(ranked_pages[:max_processable_pages])
            # Keep planned pages in natural document order
            pages_planned = [p for p in clean_pages if p in selected_set]
            pages_deferred = [p for p in clean_pages if p not in selected_set]

        # Group planned pages into batches of size N
        batches: List[List[int]] = []
        for i in range(0, len(pages_planned), size):
            batches.append(pages_planned[i : i + size])

        planned_requests = len(batches)
        remaining_budget = (request_budget - planned_requests) if request_budget is not None else None

        return QuotaPlan(
            eligible_pages_count=total_pages,
            available_requests=request_budget,
            batch_size=size,
            estimated_requests=estimated_requests,
            can_complete=can_complete,
            full_extraction_possible=can_complete,
            pages_planned=pages_planned,
            pages_deferred=pages_deferred,
            batches=batches,
            remaining_budget=remaining_budget,
        )
